/* ============================================================
   LPto0 — 24-Zone Set Summon Duel
   ============================================================ */

* { box-sizing: border-box; }

:root {
  --bg: #04050d;
  --bg-2: #070a18;
  --panel: rgba(10, 15, 32, 0.78);
  --panel-solid: #0a0f20;
  --line: rgba(124, 211, 255, 0.13);
  --line-strong: rgba(124, 211, 255, 0.32);
  --cyan: #55f4ff;
  --cyan-deep: #18a8cd;
  --pink: #ff3ea5;
  --pink-deep: #a4145f;
  --gold: #ffd166;
  --green: #7cf7c4;
  --red: #ff5d73;
  --text: #eaf7ff;
  --muted: #7f8da9;
  --muted-2: #55627d;
  --zone-w: clamp(50px, min(6.4vw, 10.4vh), 96px);
  --zone-h: calc(var(--zone-w) * 1.18);
  --gap: clamp(4px, 0.45vw, 7px);
  --hand-h: clamp(118px, 17.5vh, 166px);
  --radius: 10px;
  --font-display: "Arial Black", "Segoe UI Black", "Helvetica Neue", Impact, sans-serif;
  --font-ui: "Segoe UI", "Hiragino Kaku Gothic ProN", "Yu Gothic", "Noto Sans JP", sans-serif;
  --font-mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
}

[hidden] { display: none !important; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  min-height: 100dvh;
  overflow-x: hidden;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  touch-action: manipulation;
}

button:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

::selection { background: rgba(85, 244, 255, 0.35); }

/* ------------------------------------------------------------
   APP + BACKGROUND
   ------------------------------------------------------------ */
.app {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
  padding: 0 clamp(8px, 2vw, 28px) env(safe-area-inset-bottom);
}

.bg-layer {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% -12%, rgba(38, 91, 160, 0.28), transparent 55%),
    radial-gradient(ellipse at 8% 45%, rgba(255, 62, 165, 0.07), transparent 45%),
    radial-gradient(ellipse at 92% 52%, rgba(85, 244, 255, 0.07), transparent 45%),
    linear-gradient(180deg, #050713 0%, #04050d 55%, #02030a 100%);
}

.bg-aurora {
  position: absolute;
  width: 60vw;
  height: 60vw;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.16;
  animation: aurora 18s ease-in-out infinite alternate;
}
.bg-aurora.a {
  top: -34vw;
  left: -10vw;
  background: radial-gradient(circle, #1b7dff, transparent 65%);
}
.bg-aurora.b {
  bottom: -42vw;
  right: -12vw;
  background: radial-gradient(circle, #ff2e93, transparent 65%);
  animation-delay: -7s;
}

.bg-grid {
  position: absolute;
  left: -20%;
  right: -20%;
  bottom: -26%;
  height: 78%;
  background-image:
    linear-gradient(rgba(85, 244, 255, 0.1) 1px, transparent 1px),
    linear-gradient(90deg, rgba(85, 244, 255, 0.1) 1px, transparent 1px);
  background-size: 46px 46px;
  transform: perspective(760px) rotateX(61deg);
  transform-origin: center bottom;
  mask-image: linear-gradient(to top, #000 5%, rgba(0, 0, 0, 0.55) 45%, transparent 90%);
  -webkit-mask-image: linear-gradient(to top, #000 5%, rgba(0, 0, 0, 0.55) 45%, transparent 90%);
  opacity: 0.55;
}

.bg-scan {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.022) 0px,
    rgba(255, 255, 255, 0.022) 1px,
    transparent 1px,
    transparent 4px
  );
  mix-blend-mode: overlay;
  opacity: 0.5;
}

.fx {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 30;
  pointer-events: none;
}

/* ------------------------------------------------------------
   TOP BAR
   ------------------------------------------------------------ */
.topbar {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex: 0 0 auto;
  height: clamp(48px, 6.4vh, 62px);
  border-bottom: 1px solid var(--line);
}
.topbar::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(85, 244, 255, 0.55), rgba(255, 62, 165, 0.5), transparent);
  opacity: 0.55;
}

.brand { display: flex; align-items: center; gap: 14px; min-width: 0; }
.brand-logo {
  display: flex;
  align-items: baseline;
  font-family: var(--font-display);
  font-size: clamp(22px, 2.4vw, 33px);
  line-height: 1;
  letter-spacing: -0.035em;
  white-space: nowrap;
  text-shadow: 0 0 26px rgba(85, 244, 255, 0.35);
}
.brand-logo .lp {
  background: linear-gradient(180deg, #ffffff, #9fefff 55%, #37cfe8);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-style: italic;
}
.brand-logo .to {
  margin: 0 0.04em;
  color: var(--gold);
  font-size: 0.52em;
  letter-spacing: 0;
  transform: translateY(-0.45em);
  text-shadow: 0 0 14px rgba(255, 209, 102, 0.65);
}
.brand-logo .zero {
  color: transparent;
  -webkit-text-stroke: 1.5px var(--pink);
  text-shadow: 0 0 20px rgba(255, 62, 165, 0.55);
  font-size: 1.12em;
}

.brand-meta { display: flex; align-items: center; gap: 8px; }
.brand-sub {
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.28em;
  color: var(--muted);
  white-space: nowrap;
}
.brand-sub.alt { color: var(--cyan-deep); }
.brand-dot {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
}

.top-mid { display: flex; align-items: center; gap: 7px; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border: 1px solid var(--line);
  background: rgba(9, 14, 28, 0.66);
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.14em;
  color: var(--muted);
  white-space: nowrap;
}
.chip.gold { color: var(--gold); border-color: rgba(255, 209, 102, 0.3); }
.chip.live { color: var(--green); }
.chip.live i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 9px var(--green);
  animation: pulse 1.6s ease-in-out infinite;
}

.top-actions { display: flex; align-items: center; gap: 6px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 30px;
  padding: 6px 11px;
  border: 1px solid var(--line);
  background: rgba(10, 15, 32, 0.62);
  color: var(--muted);
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}
.btn:hover { color: var(--text); border-color: var(--line-strong); background: rgba(20, 30, 58, 0.8); }
.btn:active { transform: translateY(1px); }
.btn .btn-ico { color: var(--cyan); font-size: 12px; line-height: 1; }
.btn[aria-pressed="false"] .btn-ico { color: var(--muted-2); }

.btn.primary {
  color: #04141a;
  border-color: transparent;
  background: linear-gradient(135deg, #8af9ff, #38d6ee 45%, #1aa6c9);
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: 0.14em;
  box-shadow: 0 0 26px rgba(85, 244, 255, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.55);
}
.btn.primary:hover { filter: brightness(1.08); background: linear-gradient(135deg, #b4fcff, #55e9ff 45%, #22bfe1); }
.btn.primary.wide { width: 100%; min-height: 46px; margin-top: 18px; }
.btn.primary.xl { min-width: 220px; min-height: 52px; font-size: 15px; }

/* ------------------------------------------------------------
   ARENA LAYOUT
   ------------------------------------------------------------ */
.arena {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: minmax(190px, 238px) minmax(0, 1fr) minmax(230px, 286px);
  gap: clamp(10px, 1.4vw, 22px);
  align-items: start;
  padding: clamp(6px, 1vh, 14px) 0 0;
  min-height: 0;
}

.duel-col {
  width: 100%;
  max-width: calc(26px + 6 * var(--zone-w) + 7 * var(--gap) + 30px);
  justify-self: center;
  display: flex;
  flex-direction: column;
  gap: clamp(4px, 0.7vh, 8px);
  min-width: 0;
}

.rail {
  position: relative;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(16, 24, 48, 0.55), rgba(6, 9, 20, 0.72));
  backdrop-filter: blur(9px);
  min-height: 0;
  overflow: hidden;
}
.rail::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 44px;
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 12px var(--cyan);
  opacity: 0.7;
}
.rail-right::before { background: var(--pink); box-shadow: 0 0 12px var(--pink); left: auto; right: 0; }

.rail-head,
.rail-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  padding: 10px 11px;
}
.rail-head { border-bottom: 1px solid var(--line); }
.rail-foot {
  border-top: 1px solid var(--line);
  padding: 8px 11px;
  justify-content: space-between;
  margin-top: auto;
}
.rail-kicker {
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  color: var(--cyan);
}
.rail-right .rail-kicker { color: var(--pink); }
.rail-rule { flex: 1; height: 1px; background: linear-gradient(90deg, var(--line-strong), transparent); }
.rail-count {
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
}
.mono { font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.08em; color: var(--muted); }
.mono.dim { color: var(--muted-2); }

/* LOG */
.log {
  flex: 1 1 auto;
  min-height: 0;
  max-height: calc(100vh - 240px);
  overflow-y: auto;
  padding: 4px 0 10px;
  scrollbar-width: thin;
  scrollbar-color: rgba(85, 244, 255, 0.25) transparent;
}
.log::-webkit-scrollbar { width: 3px; }
.log::-webkit-scrollbar-thumb { background: rgba(85, 244, 255, 0.22); }
.log-entry {
  position: relative;
  display: grid;
  grid-template-columns: 25px 1fr;
  gap: 6px;
  padding: 7px 10px 7px 0;
  border-left: 1px solid transparent;
  font-size: 10px;
  line-height: 1.45;
  color: #a9b6cc;
  animation: logIn 0.28s ease both;
}
.log-entry::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: var(--line-strong);
}
.log-entry .li-num {
  font-family: var(--font-mono);
  font-size: 7px;
  color: var(--muted-2);
  text-align: right;
  padding-top: 2px;
}
.log-entry .li-text b { color: var(--text); font-weight: 700; }
.log-entry .li-text em { color: var(--gold); font-style: normal; }
.log-entry.you::before { background: var(--cyan); box-shadow: 0 0 8px rgba(85, 244, 255, 0.55); }
.log-entry.opp::before { background: var(--pink); box-shadow: 0 0 8px rgba(255, 62, 165, 0.55); }
.log-entry.sys::before { background: var(--gold); }
.log-entry.warn::before { background: var(--red); }
.log-entry.sys { color: var(--gold); }
.log-entry.warn { color: #ffb3bf; }
.log-entry.big .li-text { color: var(--text); font-size: 11px; letter-spacing: 0.02em; }

/* ------------------------------------------------------------
   HUD
   ------------------------------------------------------------ */
.hud {
  --accent: var(--cyan);
  --accent-soft: rgba(85, 244, 255, 0.16);
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  gap: clamp(6px, 0.9vw, 12px);
  flex: 0 0 auto;
  padding: clamp(5px, 0.8vh, 8px) clamp(7px, 0.8vw, 10px);
  border: 1px solid var(--line);
  background:
    linear-gradient(90deg, var(--accent-soft), transparent 34%),
    linear-gradient(180deg, rgba(13, 20, 42, 0.78), rgba(7, 10, 23, 0.88));
  overflow: visible;
}
.hud::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--accent);
  box-shadow: 0 0 14px var(--accent);
  opacity: 0.8;
}
.hud.opponent { --accent: var(--pink); --accent-soft: rgba(255, 62, 165, 0.14); }
.hud.opponent::after { left: auto; right: 0; }
.hud.active { border-color: color-mix(in srgb, var(--accent) 45%, transparent); }
.hud.active::after { opacity: 1; animation: hudGlow 1.8s ease-in-out infinite; }

.avatar {
  position: relative;
  width: clamp(36px, 4.2vw, 50px);
  height: clamp(36px, 4.2vw, 50px);
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 35%, #1a2d54, #070b17 70%);
  border: 1px solid color-mix(in srgb, var(--accent) 60%, transparent);
  box-shadow: 0 0 18px color-mix(in srgb, var(--accent) 28%, transparent), inset 0 0 18px rgba(0, 0, 0, 0.6);
}
.avatar::before {
  content: "";
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 1px dashed color-mix(in srgb, var(--accent) 45%, transparent);
  animation: spin 18s linear infinite;
}
.avatar-ring {
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 1px solid transparent;
  border-top-color: var(--accent);
  border-bottom-color: color-mix(in srgb, var(--accent) 25%, transparent);
  animation: spin 7s linear infinite reverse;
  opacity: 0.75;
}
.avatar-letter {
  font-family: var(--font-display);
  font-size: clamp(12px, 1.3vw, 17px);
  letter-spacing: -0.04em;
  color: var(--accent);
  text-shadow: 0 0 14px var(--accent);
  line-height: 1;
}
.avatar-lv {
  position: absolute;
  bottom: -6px;
  left: 50%;
  transform: translateX(-50%);
  padding: 1px 5px;
  border: 1px solid color-mix(in srgb, var(--accent) 40%, transparent);
  background: #070b17;
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.08em;
  color: var(--accent);
  white-space: nowrap;
}

.hud-body { min-width: 0; }
.hud-line { display: flex; align-items: center; gap: 8px; min-width: 0; }
.hud-name {
  font-size: clamp(11px, 1.05vw, 14px);
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #f2fbff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 0 18px color-mix(in srgb, var(--accent) 22%, transparent);
}
.hud-role {
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.14em;
  color: var(--muted-2);
  white-space: nowrap;
}
.hud-turn-flag {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.16em;
  color: var(--muted-2);
  white-space: nowrap;
}
.hud.active .hud-turn-flag { color: var(--accent); text-shadow: 0 0 10px var(--accent); }

.lp-line { display: flex; align-items: center; gap: 8px; margin-top: 4px; }
.lp-bar {
  position: relative;
  flex: 1;
  height: clamp(8px, 1.15vh, 11px);
  background: rgba(3, 6, 15, 0.9);
  border: 1px solid color-mix(in srgb, var(--accent) 22%, transparent);
  overflow: hidden;
  clip-path: polygon(3px 0, 100% 0, 100% calc(100% - 3px), calc(100% - 3px) 100%, 0 100%, 0 3px);
}
.lp-fill {
  position: absolute;
  inset: 0;
  width: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 38%, #062236), var(--accent));
  box-shadow: 0 0 16px color-mix(in srgb, var(--accent) 55%, transparent);
  transition: width 0.6s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.3s ease;
}
.lp-fill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.35), transparent 55%);
  opacity: 0.6;
}
.lp-bar.danger .lp-fill { background: linear-gradient(90deg, #5c0d20, var(--red)); box-shadow: 0 0 18px rgba(255, 93, 115, 0.55); }
.lp-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(4, 5, 13, 0.85) calc(10% - 1px), rgba(4, 5, 13, 0.85) 10%);
  opacity: 0.6;
  pointer-events: none;
}
.lp-label {
  position: absolute;
  left: 6px;
  top: 50%;
  transform: translateY(-50%);
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.18em;
  color: rgba(4, 12, 18, 0.8);
  mix-blend-mode: multiply;
  white-space: nowrap;
}
.lp-num {
  font-family: var(--font-display);
  font-size: clamp(16px, 1.7vw, 23px);
  line-height: 1;
  letter-spacing: 0.01em;
  font-variant-numeric: tabular-nums;
  color: #fff;
  text-shadow: 0 0 14px color-mix(in srgb, var(--accent) 55%, transparent);
  min-width: 3.8ch;
  text-align: right;
}
.lp-num.hit { animation: lpHit 0.4s ease; color: var(--red); }

.hud-stats { display: flex; align-items: center; gap: clamp(5px, 0.7vw, 10px); }
.stat { display: flex; flex-direction: column; align-items: center; min-width: 24px; }
.stat b {
  font-family: var(--font-mono);
  font-size: clamp(9px, 0.9vw, 11px);
  color: var(--text);
  line-height: 1.2;
  font-weight: 600;
}
.stat span {
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  color: var(--muted-2);
  line-height: 1.4;
}

.end-turn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  min-width: clamp(54px, 5.6vw, 74px);
  height: clamp(34px, 4.4vh, 44px);
  padding: 0 6px;
  border: 1px solid color-mix(in srgb, var(--cyan) 45%, transparent);
  background: linear-gradient(180deg, rgba(85, 244, 255, 0.16), rgba(10, 24, 40, 0.7));
  color: var(--cyan);
  clip-path: polygon(5px 0, 100% 0, 100% calc(100% - 5px), calc(100% - 5px) 100%, 0 100%, 0 5px);
  transition: background 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
}
.end-turn:hover:not(:disabled) {
  background: linear-gradient(180deg, rgba(85, 244, 255, 0.28), rgba(10, 24, 40, 0.8));
  box-shadow: 0 0 24px rgba(85, 244, 255, 0.18);
}
.end-turn:disabled { opacity: 0.32; cursor: not-allowed; }
.end-turn-main { font-family: var(--font-display); font-size: 8px; letter-spacing: 0.1em; }
.end-turn-key {
  font-family: var(--font-mono);
  font-size: 6px;
  color: var(--muted);
  border: 1px solid var(--line);
  padding: 0 3px;
  line-height: 1.3;
}
.end-turn.urgent { animation: endPulse 2.2s ease-in-out infinite; }

/* speech bubble */
.speech {
  position: absolute;
  top: calc(100% + 6px);
  left: 50%;
  transform: translate(-50%, -4px);
  z-index: 12;
  padding: 5px 9px;
  border: 1px solid rgba(255, 62, 165, 0.25);
  background: rgba(8, 12, 26, 0.94);
  color: #ffc4e2;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.04em;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}
.speech::before {
  content: "";
  position: absolute;
  top: -4px;
  left: 50%;
  width: 6px;
  height: 6px;
  background: rgba(8, 12, 26, 0.94);
  border-left: 1px solid rgba(255, 62, 165, 0.25);
  border-top: 1px solid rgba(255, 62, 165, 0.25);
  transform: translateX(-50%) rotate(45deg);
}
.speech.you { top: auto; bottom: calc(100% + 6px); border-color: rgba(85, 244, 255, 0.25); color: var(--cyan); }
.speech.you::before { top: auto; bottom: -4px; border: 0; border-right: 1px solid rgba(85, 244, 255, 0.25); border-bottom: 1px solid rgba(85, 244, 255, 0.25); }
.speech.show { opacity: 1; transform: translate(-50%, 0); }

/* ------------------------------------------------------------
   BOARD
   ------------------------------------------------------------ */
.board-shell {
  position: relative;
  flex: 0 0 auto;
  padding: clamp(6px, 0.85vw, 11px);
  border: 1px solid rgba(105, 180, 255, 0.16);
  background:
    linear-gradient(180deg, rgba(15, 25, 52, 0.5), rgba(4, 6, 14, 0.72)),
    radial-gradient(ellipse at 50% 50%, rgba(85, 244, 255, 0.05), transparent 65%);
  box-shadow:
    0 26px 70px rgba(0, 0, 0, 0.52),
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 0 0 1px rgba(0, 0, 0, 0.4);
  overflow: hidden;
}
.board-shell::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(85, 244, 255, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(85, 244, 255, 0.035) 1px, transparent 1px);
  background-size: 18px 18px;
  mask-image: radial-gradient(ellipse at center, #000 20%, transparent 82%);
  -webkit-mask-image: radial-gradient(ellipse at center, #000 20%, transparent 82%);
  pointer-events: none;
}
.board-shell::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(85, 244, 255, 0.06);
  pointer-events: none;
}
.board-corner {
  position: absolute;
  width: 14px;
  height: 14px;
  border-color: var(--cyan);
  opacity: 0.55;
  z-index: 2;
  pointer-events: none;
}
.board-corner.tl { top: 3px; left: 3px; border-left: 1px solid; border-top: 1px solid; }
.board-corner.tr { top: 3px; right: 3px; border-right: 1px solid; border-top: 1px solid; }
.board-corner.bl { bottom: 3px; left: 3px; border-left: 1px solid; border-bottom: 1px solid; }
.board-corner.br { bottom: 3px; right: 3px; border-right: 1px solid; border-bottom: 1px solid; }

.board {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  width: calc(26px + 6 * var(--zone-w) + 7 * var(--gap));
  max-width: 100%;
  margin: 0 auto;
}

.row { display: flex; align-items: stretch; gap: var(--gap); }
.row-label {
  width: 19px;
  flex: 0 0 19px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-family: var(--font-mono);
  font-size: 6px;
  letter-spacing: 0.18em;
  color: var(--muted-2);
  opacity: 0.75;
  user-select: none;
}
.row-label em { font-style: normal; color: rgba(85, 244, 255, 0.5); }
.row-label i { font-style: normal; color: rgba(255, 62, 165, 0.38); }
.row[data-side="player"] .row-label em { color: rgba(85, 244, 255, 0.62); }

.zones {
  display: grid;
  grid-template-columns: repeat(6, var(--zone-w));
  gap: var(--gap);
  flex: 0 0 auto;
}

.zone {
  position: relative;
  width: var(--zone-w);
  height: var(--zone-h);
  border: 1px solid rgba(120, 190, 255, 0.11);
  background:
    linear-gradient(180deg, rgba(22, 36, 72, 0.28), rgba(5, 8, 19, 0.66));
  clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
  transition: border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
  cursor: default;
  isolation: isolate;
}
.zone::before {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(255, 255, 255, 0.035);
  clip-path: polygon(4px 0, 100% 0, 100% calc(100% - 4px), calc(100% - 4px) 100%, 0 100%, 0 4px);
  pointer-events: none;
  z-index: 1;
}
.zone::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.018) 0 1px, transparent 1px 7px);
  pointer-events: none;
  opacity: 0.7;
}
.row[data-side="opponent"] .zone { border-color: rgba(255, 100, 180, 0.13); }
.row[data-side="player"] .zone { border-color: rgba(100, 220, 255, 0.14); }
.row[data-kind="monster"] .zone { background: linear-gradient(180deg, rgba(28, 47, 92, 0.3), rgba(5, 8, 19, 0.7)); }
.row[data-kind="spell"] .zone { background: linear-gradient(180deg, rgba(15, 24, 48, 0.34), rgba(4, 6, 15, 0.72)); }

.zone-coord {
  position: absolute;
  top: 2px;
  left: 5px;
  font-family: var(--font-mono);
  font-size: 5px;
  letter-spacing: 0.06em;
  color: rgba(127, 141, 169, 0.42);
  z-index: 2;
  pointer-events: none;
}
.zone-hint {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-family: var(--font-mono);
  font-size: 6px;
  letter-spacing: 0.14em;
  color: rgba(127, 141, 169, 0.22);
  user-select: none;
  pointer-events: none;
  z-index: 1;
}
.zone-hint::before {
  content: "";
  position: absolute;
  width: 34%;
  height: 34%;
  border: 1px solid rgba(127, 141, 169, 0.16);
  transform: rotate(45deg);
}
.row[data-kind="monster"] .zone-hint::before {
  transform: none;
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
  border: 0;
  background: rgba(127, 141, 169, 0.08);
}
.zone.occupied .zone-hint { display: none; }
.zone.occupied { border-color: transparent; background: transparent; }
.zone .card { position: absolute; inset: 0; z-index: 2; }

.zone.valid {
  cursor: pointer;
  border-color: rgba(85, 244, 255, 0.65);
  background: linear-gradient(180deg, rgba(85, 244, 255, 0.16), rgba(9, 18, 35, 0.75));
  animation: zonePulse 1.6s ease-in-out infinite;
}
.zone.valid .zone-hint { color: rgba(85, 244, 255, 0.85); }
.zone.valid .zone-hint::before { background: rgba(85, 244, 255, 0.2); border-color: rgba(85, 244, 255, 0.5); }
.zone.valid:hover {
  border-color: var(--cyan);
  background: linear-gradient(180deg, rgba(85, 244, 255, 0.27), rgba(9, 18, 35, 0.82));
  box-shadow: inset 0 0 24px rgba(85, 244, 255, 0.12);
}

.zone.targetable {
  cursor: crosshair;
  border-color: rgba(255, 62, 165, 0.7);
  animation: targetPulse 1.15s ease-in-out infinite;
}
.zone.targetable::before { border-color: rgba(255, 62, 165, 0.28); }
.zone.targetable:hover { border-color: var(--pink); box-shadow: inset 0 0 28px rgba(255, 62, 165, 0.18); }
.zone.targetable .card { filter: saturate(1.15) brightness(1.06); }

.zone.selected {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px rgba(255, 209, 102, 0.35), 0 0 24px rgba(255, 209, 102, 0.24);
}
.zone.selected::before { border-color: rgba(255, 209, 102, 0.4); }
.zone.selected .card { filter: brightness(1.08); }

.zone.battle-flash { animation: battleFlash 0.42s ease; }
.zone.summon-flash .card { animation: summonPop 0.5s cubic-bezier(0.16, 1, 0.3, 1); }

/* divider */
.divider {
  position: relative;
  display: flex;
  align-items: center;
  gap: 9px;
  height: clamp(26px, 3.4vh, 36px);
  padding: 0 2px;
}
.divider-line {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(85, 244, 255, 0.38), rgba(255, 62, 165, 0.38), transparent);
}
.turn-core {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  min-width: 104px;
  padding: 4px 14px;
  border: 1px solid rgba(255, 209, 102, 0.24);
  background: linear-gradient(180deg, rgba(22, 20, 28, 0.78), rgba(6, 8, 17, 0.9));
  clip-path: polygon(6px 0, 100% 0, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0 100%, 0 6px);
}
.turn-core::before,
.turn-core::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 18px;
  height: 1px;
  background: rgba(255, 209, 102, 0.25);
}
.turn-core::before { left: -18px; }
.turn-core::after { right: -18px; }
.turn-kicker {
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.22em;
  color: var(--muted);
}
.turn-phase {
  font-family: var(--font-display);
  font-size: clamp(9px, 0.9vw, 11px);
  letter-spacing: 0.16em;
  color: var(--gold);
  text-shadow: 0 0 14px rgba(255, 209, 102, 0.35);
  white-space: nowrap;
}
.turn-phase.opp { color: var(--pink); text-shadow: 0 0 14px rgba(255, 62, 165, 0.4); }
.turn-phase.busy { color: var(--muted); text-shadow: none; }
.divider-code {
  position: absolute;
  right: 2px;
  bottom: -3px;
  font-family: var(--font-mono);
  font-size: 5px;
  letter-spacing: 0.16em;
  color: rgba(127, 141, 169, 0.32);
  pointer-events: none;
}

/* ------------------------------------------------------------
   CARDS
   ------------------------------------------------------------ */
.card {
  position: relative;
  width: 100%;
  height: 100%;
  container-type: size;
  display: flex;
  flex-direction: column;
  border-radius: 5px;
  border: 1px solid color-mix(in srgb, var(--c1, #6ea8ff) 55%, transparent);
  background: linear-gradient(170deg, #121a33 0%, #080c18 55%, #05070f 100%);
  overflow: hidden;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.35), inset 0 0 0 1px rgba(255, 255, 255, 0.03);
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
  user-select: none;
}
.card::after {
  content: "";
  position: absolute;
  inset: 0;
  box-shadow: inset 0 0 22px color-mix(in srgb, var(--glow, #6ea8ff) 20%, transparent);
  pointer-events: none;
  z-index: 4;
}
.card-art {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 72% 18%, rgba(255, 255, 255, 0.35), transparent 24%),
    radial-gradient(circle at 24% 78%, color-mix(in srgb, var(--c2, #123) 65%, transparent), transparent 58%),
    linear-gradient(140deg, var(--c1, #2b6cff) 0%, var(--c2, #111a3a) 100%);
}
.card-art::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(0, 0, 0, 0.13) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.09) 1px, transparent 1px);
  background-size: 12% 12%;
  opacity: 0.42;
  mix-blend-mode: overlay;
}
.card-art::after {
  content: "";
  position: absolute;
  inset: -40% -20%;
  background: linear-gradient(115deg, transparent 42%, rgba(255, 255, 255, 0.36) 49%, transparent 56%);
  transform: translateX(-40%);
  transition: transform 0.6s ease;
  opacity: 0.5;
}
.card:hover .card-art::after { transform: translateX(40%); }

.card-glyph {
  position: absolute;
  left: 50%;
  top: 49%;
  transform: translate(-50%, -50%);
  font-family: "Yu Mincho", "Hiragino Mincho ProN", "Noto Serif JP", serif;
  font-size: 46cqw;
  line-height: 1;
  font-weight: 900;
  color: rgba(255, 255, 255, 0.88);
  text-shadow:
    0 0 3cqw rgba(255, 255, 255, 0.65),
    0 0 9cqw color-mix(in srgb, var(--glow, #6ea8ff) 70%, transparent),
    0 3cqw 4cqw rgba(0, 0, 0, 0.45);
  mix-blend-mode: screen;
}
.card-element {
  position: absolute;
  top: 3%;
  right: 5%;
  font-family: var(--font-mono);
  font-size: 6cqw;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.8);
  text-shadow: 0 0 6px rgba(0, 0, 0, 0.6);
  z-index: 2;
}
.card-type-tag {
  position: absolute;
  top: 4%;
  right: 5%;
  padding: 1cqw 2cqw;
  border: 1px solid rgba(255, 255, 255, 0.4);
  background: rgba(0, 0, 0, 0.28);
  font-family: var(--font-mono);
  font-size: 5.5cqw;
  letter-spacing: 0.1em;
  color: #fff;
  z-index: 2;
}
.card-level {
  position: absolute;
  left: 5%;
  bottom: 3%;
  font-size: 6cqw;
  letter-spacing: -0.06em;
  color: #ffe8a3;
  text-shadow: 0 0 6px rgba(255, 190, 60, 0.8), 0 1px 2px #000;
  z-index: 2;
}
.card-body {
  position: relative;
  flex: 0 0 auto;
  padding: 4cqw 5cqw 5cqw;
  background: linear-gradient(180deg, rgba(7, 10, 20, 0.86), rgba(4, 6, 13, 0.98));
  border-top: 1px solid color-mix(in srgb, var(--c1, #6ea8ff) 45%, transparent);
  z-index: 3;
}
.card-title {
  font-family: var(--font-display);
  font-size: 8.2cqw;
  line-height: 1.05;
  letter-spacing: 0.015em;
  color: #f4fbff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 0 8px color-mix(in srgb, var(--glow, #6ea8ff) 30%, transparent);
}
.card-jp {
  margin-top: 1.5cqw;
  font-size: 6cqw;
  line-height: 1.1;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.card-stats {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 2cqw;
  margin-top: 3cqw;
}
.card-stats span {
  display: inline-flex;
  align-items: baseline;
  gap: 2cqw;
  font-family: var(--font-mono);
  font-size: 8.2cqw;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: #ffd9a1;
  white-space: nowrap;
}
.card-stats span.def { color: #9fe9ff; }
.card-stats i {
  font-style: normal;
  font-size: 5cqw;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.4);
  font-weight: 400;
}
.card-stats .buffed { color: var(--green); text-shadow: 0 0 8px rgba(124, 247, 196, 0.5); }
.card-effect-line {
  margin-top: 2cqw;
  font-size: 6.2cqw;
  line-height: 1.2;
  color: #a9b6cc;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.card.face-down { border-color: rgba(147, 197, 253, 0.35); }
.card-back {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 50% 38%, rgba(85, 244, 255, 0.17), transparent 52%),
    repeating-linear-gradient(45deg, rgba(255, 62, 165, 0.07) 0 1px, transparent 1px 8px),
    repeating-linear-gradient(-45deg, rgba(85, 244, 255, 0.05) 0 1px, transparent 1px 8px),
    linear-gradient(160deg, #101a3b, #070a16 60%, #0b1024);
  overflow: hidden;
}
.card-back::before {
  content: "";
  position: absolute;
  width: 66%;
  height: 66%;
  border: 1px solid rgba(85, 244, 255, 0.22);
  transform: rotate(45deg);
  box-shadow: 0 0 24px rgba(85, 244, 255, 0.1), inset 0 0 24px rgba(85, 244, 255, 0.06);
}
.card-back::after {
  content: "";
  position: absolute;
  width: 46%;
  height: 46%;
  border: 1px solid rgba(255, 62, 165, 0.25);
  transform: rotate(45deg);
}
.back-mark {
  position: relative;
  z-index: 2;
  font-family: var(--font-display);
  font-size: 19cqw;
  letter-spacing: -0.06em;
  color: rgba(224, 251, 255, 0.9);
  text-shadow: 0 0 12px rgba(85, 244, 255, 0.65);
  transform: rotate(-45deg);
  line-height: 1;
}
.back-mark span { color: var(--gold); font-size: 0.5em; vertical-align: 0.4em; }
.back-mark b { color: var(--pink); }

/* position badge */
.pos-badge {
  position: absolute;
  z-index: 6;
  left: 3px;
  bottom: 3px;
  padding: 1px 4px;
  font-family: var(--font-mono);
  font-size: 5.5px;
  letter-spacing: 0.1em;
  line-height: 1.4;
  color: #071018;
  background: var(--gold);
  clip-path: polygon(2px 0, 100% 0, 100% calc(100% - 2px), calc(100% - 2px) 100%, 0 100%, 0 2px);
  pointer-events: none;
}
.pos-badge.def { background: #9fe9ff; }
.pos-badge.set { background: #a78bfa; color: #0b0718; }
.pos-badge.buffed { background: var(--green); }

/* ------------------------------------------------------------
   ACTION STRIP
   ------------------------------------------------------------ */
.action-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex: 0 0 auto;
  min-height: clamp(30px, 4vh, 38px);
  padding: 3px 7px 3px 10px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: linear-gradient(90deg, rgba(85, 244, 255, 0.04), rgba(6, 9, 20, 0.7) 45%, rgba(255, 62, 165, 0.05));
}
.action-status {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  font-size: 9px;
  letter-spacing: 0.02em;
  color: #a9b6cc;
}
.action-status #status-text {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.status-dot {
  flex: 0 0 auto;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
  animation: pulse 1.8s ease-in-out infinite;
}
.status-dot.opp { background: var(--pink); box-shadow: 0 0 9px var(--pink); }
.status-dot.warn { background: var(--gold); box-shadow: 0 0 9px var(--gold); }
.status-dot.busy { background: var(--muted); box-shadow: none; animation-duration: 0.6s; }
.action-buttons { display: flex; align-items: center; gap: 5px; flex: 0 0 auto; }
.act-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 24px;
  padding: 3px 9px;
  border: 1px solid var(--line-strong);
  background: rgba(10, 18, 38, 0.8);
  color: #cfe8f7;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
  white-space: nowrap;
}
.act-btn:hover { border-color: var(--cyan); color: var(--cyan); background: rgba(85, 244, 255, 0.08); }
.act-btn.active { background: rgba(85, 244, 255, 0.16); border-color: var(--cyan); color: var(--cyan); box-shadow: 0 0 14px rgba(85, 244, 255, 0.16); }
.act-btn.danger { border-color: rgba(255, 93, 115, 0.45); color: #ffb3bf; }
.act-btn.warn { border-color: rgba(255, 209, 102, 0.45); color: var(--gold); }
.act-btn:disabled { opacity: 0.3; cursor: not-allowed; }
.act-btn .k { font-size: 7px; color: var(--muted); }

/* ------------------------------------------------------------
   HAND
   ------------------------------------------------------------ */
.hand-zone {
  position: relative;
  flex: 0 0 auto;
  padding-top: 5px;
  min-height: calc(var(--hand-h) + 30px);
}
.hand-head {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 4px 3px;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: var(--muted-2);
}
.hand-title { color: var(--cyan); }
.hand-count { color: var(--text); }
.hand-hint { margin-left: auto; font-size: 6px; letter-spacing: 0.12em; color: var(--muted-2); }
.hand {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  height: var(--hand-h);
  padding: 0 8px;
  z-index: 3;
}
.hand-floor {
  position: absolute;
  left: 6%;
  right: 6%;
  bottom: 2px;
  height: 24px;
  background: radial-gradient(ellipse at center, rgba(85, 244, 255, 0.18), transparent 68%);
  filter: blur(9px);
  pointer-events: none;
}
.hand-card {
  position: relative;
  flex: 0 0 auto;
  width: clamp(84px, 7.4vw, 112px);
  aspect-ratio: 0.72;
  margin-left: -15px;
  padding: 0;
  border-radius: 7px;
  background: transparent;
  transform-origin: 50% 100%;
  transform: rotate(var(--rot, 0deg)) translateY(var(--lift, 0px));
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1), filter 0.2s ease;
  z-index: calc(10 + var(--i, 0));
  text-align: left;
}
.hand-card:first-child { margin-left: 0; }
.hand-card .card { box-shadow: 0 14px 30px rgba(0, 0, 0, 0.55); }
.hand-card:hover,
.hand-card:focus-visible {
  transform: rotate(0deg) translateY(-16px) scale(1.06);
  z-index: 40;
}
.hand-card:hover .card,
.hand-card:focus-visible .card { box-shadow: 0 22px 44px rgba(0, 0, 0, 0.65), 0 0 24px color-mix(in srgb, var(--glow) 24%, transparent); }
.hand-card.selected {
  transform: rotate(0deg) translateY(-24px) scale(1.075);
  z-index: 45;
}
.hand-card.selected .card {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px rgba(255, 209, 102, 0.65), 0 20px 42px rgba(0, 0, 0, 0.65), 0 0 30px rgba(255, 209, 102, 0.22);
}
.hand-card.dim { filter: saturate(0.55) brightness(0.68); }
.hand-card .card-title { font-size: 8.6cqw; }
.hand-card .card-jp { font-size: 5.7cqw; }
.hand-card .card-stats span { font-size: 8.5cqw; }
.hand-card .card-art { min-height: 52%; }

/* mobile detail */
.mobile-detail {
  display: none;
  align-items: center;
  gap: 8px;
  min-height: 34px;
  padding: 5px 9px;
  border: 1px solid var(--line);
  background: rgba(8, 13, 28, 0.92);
  font-size: 9px;
  line-height: 1.35;
  color: #b9c6da;
}
.mobile-detail b { color: var(--text); }
.mobile-detail .md-stats { color: var(--gold); font-family: var(--font-mono); font-size: 8px; white-space: nowrap; }
.mobile-detail .md-type { color: var(--cyan); font-family: var(--font-mono); font-size: 7px; letter-spacing: 0.1em; white-space: nowrap; }

/* ------------------------------------------------------------
   INSPECTOR
   ------------------------------------------------------------ */
.inspector {
  flex: 1 1 auto;
  min-height: 0;
  padding: 12px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 62, 165, 0.25) transparent;
}
.inspector::-webkit-scrollbar { width: 3px; }
.inspector::-webkit-scrollbar-thumb { background: rgba(255, 62, 165, 0.24); }

.inspect-empty { display: flex; flex-direction: column; height: 100%; min-height: 380px; }
.inspect-glyph {
  position: relative;
  align-self: center;
  width: 118px;
  height: 118px;
  margin: 12px 0 20px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(85, 244, 255, 0.18);
  transform: rotate(45deg);
}
.inspect-glyph::before {
  content: "";
  position: absolute;
  inset: 12px;
  border: 1px solid rgba(255, 62, 165, 0.16);
}
.inspect-glyph::after {
  content: "24";
  transform: rotate(-45deg);
  font-family: var(--font-display);
  font-size: 42px;
  color: rgba(85, 244, 255, 0.8);
  text-shadow: 0 0 28px rgba(85, 244, 255, 0.35);
}
.inspect-empty h3 {
  margin: 0 0 6px;
  font-family: var(--font-display);
  font-size: 12px;
  letter-spacing: 0.12em;
  color: var(--text);
}
.inspect-empty p { margin: 0 0 14px; font-size: 10px; line-height: 1.6; color: var(--muted); }
.inspect-list { display: flex; flex-direction: column; gap: 7px; margin-top: auto; }
.inspect-list div {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding-top: 7px;
  border-top: 1px solid var(--line);
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}
.inspect-list div b { color: var(--cyan); font-weight: 500; }
.inspect-list div b.pink { color: var(--pink); }

.inspect-card-wrap { width: 100%; max-width: 208px; margin: 4px auto 12px; aspect-ratio: 0.72; }
.inspect-card-wrap .card { box-shadow: 0 20px 42px rgba(0, 0, 0, 0.55), 0 0 28px color-mix(in srgb, var(--glow) 18%, transparent); }
.inspect-title { font-family: var(--font-display); font-size: 14px; letter-spacing: 0.03em; margin: 0 0 2px; }
.inspect-jp { font-size: 10px; color: var(--muted); margin-bottom: 9px; }
.inspect-type {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  padding: 2px 6px;
  border: 1px solid var(--line-strong);
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.12em;
  color: var(--cyan);
  margin-bottom: 10px;
}
.inspect-type.trap { color: var(--pink); border-color: rgba(255, 62, 165, 0.3); }
.inspect-effect {
  padding: 9px 10px;
  border-left: 2px solid var(--cyan);
  background: linear-gradient(90deg, rgba(85, 244, 255, 0.06), transparent);
  font-size: 10px;
  line-height: 1.6;
  color: #c4d2e6;
}
.inspect-effect.trap { border-color: var(--pink); background: linear-gradient(90deg, rgba(255, 62, 165, 0.06), transparent); }
.inspect-meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  margin-top: 10px;
  background: var(--line);
  border: 1px solid var(--line);
}
.inspect-meta div { padding: 7px 8px; background: rgba(7, 10, 22, 0.9); }
.inspect-meta span { display: block; font-family: var(--font-mono); font-size: 5.5px; letter-spacing: 0.12em; color: var(--muted-2); margin-bottom: 2px; }
.inspect-meta b { font-family: var(--font-mono); font-size: 10px; color: var(--text); font-weight: 600; }
.inspect-note { margin-top: 11px; font-size: 9px; line-height: 1.55; color: var(--muted); }
.inspect-note b { color: var(--gold); }

/* ------------------------------------------------------------
   FOOTER
   ------------------------------------------------------------ */
.footer {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 5px 0 7px;
  font-family: var(--font-mono);
  font-size: 6.5px;
  letter-spacing: 0.12em;
  color: var(--muted-2);
  border-top: 1px solid rgba(124, 211, 255, 0.06);
}
.footer b { color: var(--muted); font-weight: 500; }
.footer .dot { width: 2px; height: 2px; border-radius: 50%; background: var(--muted-2); }

/* ------------------------------------------------------------
   BANNER
   ------------------------------------------------------------ */
.banner {
  position: fixed;
  left: 50%;
  top: 38%;
  z-index: 60;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.3s ease;
  width: min(92vw, 720px);
  text-align: center;
}
.banner.show { opacity: 1; }
.banner-text {
  font-family: var(--font-display);
  font-size: clamp(30px, 6vw, 70px);
  line-height: 1;
  letter-spacing: 0.08em;
  color: #fff;
  text-shadow: 0 0 36px rgba(85, 244, 255, 0.7), 0 0 90px rgba(85, 244, 255, 0.3);
  animation: bannerIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.banner-sub {
  font-family: var(--font-mono);
  font-size: clamp(8px, 1vw, 11px);
  letter-spacing: 0.3em;
  color: var(--gold);
  text-transform: uppercase;
}
.banner-rule { width: 42%; height: 1px; background: linear-gradient(90deg, transparent, rgba(85, 244, 255, 0.7), transparent); }
.banner.opp .banner-text { text-shadow: 0 0 36px rgba(255, 62, 165, 0.7), 0 0 90px rgba(255, 62, 165, 0.3); }
.banner.opp .banner-sub { color: #ff9fce; }

/* ------------------------------------------------------------
   OVERLAYS / MODALS
   ------------------------------------------------------------ */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(2, 4, 12, 0.78);
  backdrop-filter: blur(8px);
  animation: overlayIn 0.25s ease;
  overflow-y: auto;
}
.modal {
  position: relative;
  width: min(760px, 100%);
  max-height: calc(100dvh - 36px);
  overflow-y: auto;
  padding: clamp(20px, 3.2vw, 38px);
  border: 1px solid rgba(85, 244, 255, 0.24);
  background:
    linear-gradient(160deg, rgba(18, 29, 60, 0.96), rgba(5, 8, 18, 0.98) 55%),
    #060913;
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.7), 0 0 60px rgba(85, 244, 255, 0.07);
  clip-path: polygon(18px 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%, 0 18px);
  scrollbar-width: thin;
  scrollbar-color: rgba(85, 244, 255, 0.25) transparent;
}
.modal::before {
  content: "";
  position: absolute;
  top: 0;
  left: 18px;
  width: 120px;
  height: 2px;
  background: var(--cyan);
  box-shadow: 0 0 18px var(--cyan);
}
.modal-close {
  position: absolute;
  top: 10px;
  right: 12px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  font-size: 20px;
  line-height: 1;
  color: var(--muted);
  z-index: 2;
}
.modal-close:hover { color: var(--text); border-color: var(--pink); }
.modal-kicker {
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.28em;
  color: var(--pink);
}
.modal-title {
  margin: 6px 0 4px;
  font-family: var(--font-display);
  font-size: clamp(42px, 7vw, 76px);
  line-height: 0.9;
  letter-spacing: -0.04em;
  color: transparent;
  -webkit-text-stroke: 1px rgba(85, 244, 255, 0.85);
}
.modal-title span { -webkit-text-stroke: 0; color: var(--gold); font-size: 0.42em; vertical-align: 0.75em; }
.modal-lead {
  max-width: 560px;
  margin: 0 0 20px;
  font-size: 12px;
  line-height: 1.65;
  color: var(--muted);
}
.rules-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line); border: 1px solid var(--line); }
.rule {
  position: relative;
  padding: 14px 14px 15px;
  background: rgba(7, 11, 24, 0.92);
}
.rule-num {
  position: absolute;
  top: 12px;
  right: 12px;
  font-family: var(--font-mono);
  font-size: 8px;
  color: rgba(85, 244, 255, 0.34);
}
.rule h3 {
  margin: 0 0 5px;
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.14em;
  color: var(--cyan);
}
.rule p { margin: 0; font-size: 10px; line-height: 1.6; color: #9dabc2; }
.rule p b { color: var(--text); font-weight: 600; }
.rules-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 15px;
  font-family: var(--font-mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  color: var(--muted-2);
}
.rules-keys kbd {
  margin-right: 4px;
  padding: 2px 5px;
  border: 1px solid var(--line-strong);
  background: rgba(85, 244, 255, 0.06);
  color: var(--cyan);
  font-family: var(--font-mono);
  font-size: 7px;
}

/* game over */
.overlay.gameover {
  background:
    radial-gradient(ellipse at 50% 35%, rgba(85, 244, 255, 0.13), transparent 45%),
    rgba(2, 4, 12, 0.9);
}
.overlay.gameover.lose {
  background:
    radial-gradient(ellipse at 50% 35%, rgba(255, 62, 165, 0.14), transparent 45%),
    rgba(2, 4, 12, 0.92);
}
.gameover-inner { text-align: center; max-width: 620px; padding: 20px; }
.go-kicker {
  display: inline-block;
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: 0.34em;
  color: var(--gold);
  margin-bottom: 10px;
}
.go-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(56px, 12vw, 130px);
  line-height: 0.82;
  letter-spacing: -0.02em;
  color: transparent;
  -webkit-text-stroke: 1.5px var(--cyan);
  text-shadow: 0 0 70px rgba(85, 244, 255, 0.4);
  animation: goIn 0.65s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.overlay.gameover.lose .go-title { -webkit-text-stroke-color: var(--pink); text-shadow: 0 0 70px rgba(255, 62, 165, 0.4); }
.go-sub {
  margin: 12px 0 26px;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--muted);
}
.go-stats {
  display: flex;
  justify-content: center;
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  margin-bottom: 20px;
}
.go-stats div { flex: 1; padding: 12px 8px; background: rgba(6, 10, 22, 0.92); }
.go-stats b {
  display: block;
  font-family: var(--font-display);
  font-size: clamp(18px, 2.4vw, 27px);
  color: var(--text);
  margin-bottom: 3px;
}
.go-stats span { font-family: var(--font-mono); font-size: 6px; letter-spacing: 0.16em; color: var(--muted-2); }
.go-quote {
  min-height: 34px;
  margin-bottom: 20px;
  font-size: 12px;
  line-height: 1.6;
  color: #b9c6da;
  font-style: italic;
}

/* ------------------------------------------------------------
   ANIMATIONS
   ------------------------------------------------------------ */
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes aurora { 0% { transform: translate3d(0, 0, 0) scale(1); } 100% { transform: translate3d(4vw, 3vw, 0) scale(1.15); } }
@keyframes hudGlow { 0%, 100% { opacity: 0.6; } 50% { opacity: 1; } }
@keyframes zonePulse {
  0%, 100% { box-shadow: inset 0 0 0 rgba(85, 244, 255, 0); }
  50% { box-shadow: inset 0 0 24px rgba(85, 244, 255, 0.11); }
}
@keyframes targetPulse {
  0%, 100% { box-shadow: inset 0 0 0 rgba(255, 62, 165, 0); }
  50% { box-shadow: inset 0 0 26px rgba(255, 62, 165, 0.2); }
}
@keyframes lpHit { 0% { transform: scale(1); } 35% { transform: scale(1.16); } 100% { transform: scale(1); } }
@keyframes endPulse {
  0%, 100% { box-shadow: 0 0 0 rgba(85, 244, 255, 0); border-color: rgba(85, 244, 255, 0.45); }
  50% { box-shadow: 0 0 24px rgba(85, 244, 255, 0.3); border-color: var(--cyan); }
}
@keyframes logIn { from { opacity: 0; transform: translateX(-5px); } to { opacity: 1; transform: none; } }
@keyframes summonPop {
  0% { transform: scale(0.72); filter: brightness(1.8); }
  60% { transform: scale(1.05); }
  100% { transform: scale(1); filter: brightness(1); }
}
@keyframes battleFlash {
  0% { filter: brightness(2.2); background: rgba(255, 255, 255, 0.28); }
  100% { filter: brightness(1); }
}
@keyframes bannerIn {
  0% { opacity: 0; transform: translateY(16px) scale(0.94); letter-spacing: 0.3em; }
  100% { opacity: 1; transform: none; letter-spacing: 0.08em; }
}
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes goIn { from { opacity: 0; transform: scale(0.86); } to { opacity: 1; transform: none; } }
@keyframes shake {
  0%, 100% { transform: translate(0, 0); }
  20% { transform: translate(-4px, 2px); }
