  60% { transform: translate(-3px, -1px); }
  80% { transform: translate(2px, 1px); }
}
.app.shake { animation: shake 0.32s ease; }

/* floating damage */
.float-text {
  position: fixed;
  z-index: 70;
  transform: translate(-50%, -50%);
  font-family: var(--font-display);
  font-size: clamp(16px, 2.4vw, 30px);
