}
.float-text.heal { color: var(--green); }
.float-text.damage { color: #ff8095; }
.float-text.gold { color: var(--gold); }
@keyframes floatUp {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.7); }
  18% { opacity: 1; transform: translate(-50%, -70%) scale(1.12); }
  100% { opacity: 0; transform: translate(-50%, -180%) scale(0.95); }
}

/* flying card clone */
.fly-card {
  position: fixed;
  z-index: 80;
  pointer-events: none;
  transform-origin: center;
  filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.6));
  transition: none;
}
.slash {
  position: fixed;
  z-index: 65;
  height: 2px;
  transform-origin: left center;
  background: linear-gradient(90deg, transparent, #fff 20%, var(--cyan) 50%, transparent);
  box-shadow: 0 0 18px var(--cyan), 0 0 42px rgba(85, 244, 255, 0.5);
  pointer-events: none;
  animation: slashOut 0.42s ease-out forwards;
}
.slash.pink { background: linear-gradient(90deg, transparent, #fff 20%, var(--pink) 50%, transparent); box-shadow: 0 0 18px var(--pink), 0 0 42px rgba(255, 62, 165, 0.5); }
@keyframes slashOut {
  0% { opacity: 0; transform: scaleX(0.3); }
  25% { opacity: 1; }
  100% { opacity: 0; transform: scaleX(1); }
}

